window.DIGEST.foryou.push(...[{"id": "2112955412752568714", "url": "https://x.com/aisearchio/status/2112955412752568714", "text": "Clever hack to use MOSS with reference images\n\nhttps://github.com/ThetaCursed/ComfyUI-MOSSImageTextEncoder", "name": "AI Search", "handle": "aisearchio", "avatar": "https://pbs.twimg.com/profile_images/1766883795150479360/uu_KeDD1_200x200.jpg", "likes": 328, "rts": 19, "replies": 2, "views": 14657, "ts": 1792602801, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVK5l42boAASLuD.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.03, "thread": [], "tier": "must"}, {"id": "2112924874435964954", "url": "https://x.com/googleespanol/status/2112924874435964954", "text": "Estudiar sin perder la concentración sí es posible 💻📚\n\nGemini en Google Chrome ahora te hace quizzes interactivos con tus notas, resume videos de estudio y lee tus textos en voz alta para que repases en el camino.\n\n📑 Pantalla dividida para estudiar y redactar al mismo tiempo\n🎧 Lectura en voz alta para escuchar tus textos en el camino\n📱 Sincronización exacta de tus pestañas entre la laptop y tu celular\n\n¿Eras de los que ya usaba estos atajos o te acabas de enterar? Cuéntanos en las respuestas 👇👀", "name": "Google en español", "handle": "googleespanol", "avatar": "https://pbs.twimg.com/profile_images/2001678065701675008/2CEHA0LD_200x200.jpg", "likes": 282, "rts": 47, "replies": 2, "views": 10827, "ts": 1792595520, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112924850461270017/vid/avc1/618x360/qN6crwHj-9Y2btEK.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112924850461270017/vid/avc1/1238x720/-nXJEJgTZLu7p0TA.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112924850461270017/img/Q1AE2nEkR-ZGIw44.jpg", "dur": 6}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.03, "thread": [], "tier": "must"}, {"id": "2113058719806488974", "url": "https://x.com/jornalnacional/status/2113058719806488974", "text": "PF acha sala secreta em hangar de aeroporto e suspeita que local era usado por Willer Tomaz para guardar dinheiro vivo. \n\nTomaz e Flávio Bolsonaro, candidato do PL à Presidência, são investigados por lavagem de dinheiro.\n\nVeja a reportagem completa: https://glo.bo/4zFDRv4 #JN", "name": "Jornal Nacional", "handle": "jornalnacional", "avatar": "https://pbs.twimg.com/profile_images/1961533244219772928/YIQUEAU7_200x200.jpg", "likes": 20045, "rts": 7042, "replies": 1410, "views": 434358, "ts": 1792627432, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2113058519142273024/vid/avc1/1280x720/bh8xAIc8tDrdgYjG.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2113058519142273024/vid/avc1/1920x1080/DFir1QDPnHod5jji.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2113058519142273024/img/Rq7BUIiVfQNiu3_P.jpg", "dur": 224}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 6.03, "thread": [], "tier": "must"}, {"id": "2112984783068561883", "url": "https://x.com/LuminaBench/status/2112984783068561883", "text": "Anthropic are launching Claude Duet\n\nThis looks like their version of Grok bot / OpenAI's dots from what I can see", "name": "Lumina", "handle": "LuminaBench", "avatar": "https://pbs.twimg.com/profile_images/2062955151820787712/m39pUS7O_200x200.jpg", "likes": 292, "rts": 5, "replies": 18, "views": 10078, "ts": 1792609804, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVLTWNyW8AIIsPb.png?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 6.02, "thread": [], "tier": "must"}, {"id": "2112922093998448869", "url": "https://x.com/AndrewCurran_/status/2112922093998448869", "text": "Call the ambulance! But not for me.", "name": "Andrew Curran", "handle": "AndrewCurran_", "avatar": "https://pbs.twimg.com/profile_images/1596945208058744833/_X3LT7fb_200x200.jpg", "likes": 313, "rts": 11, "replies": 37, "views": 14833, "ts": 1792594858, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVKbcj3bsAEXCVv.jpg?name=orig"}], "quote": {"id": "2112819774573179175", "url": "https://x.com/UnitreeRobotics/status/2112819774573179175", "text": "Unitree Introducing: H2-X Kung Fu Legend Guardian🤖\nPowerful performance to serve and guard you, with a maximum endurance of approximately 8 hours.\nPlease use the robot safely and in a friendly manner.", "name": "Unitree", "handle": "UnitreeRobotics", "avatar": "https://pbs.twimg.com/profile_images/1844926705389142016/nIEbH8rV_200x200.jpg", "likes": 20512, "rts": 2766, "replies": 1427, "views": 4243630, "ts": 1792570463, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112814220194828288/vid/avc1/1280x720/qQFeTMrcQITPE76L.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112814220194828288/vid/avc1/1920x1080/dphHVlNFst1G9RW0.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112814220194828288/img/RL8lXu0dfq4qop9M.jpg", "dur": 61}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 6.02, "thread": [], "tier": "must"}, {"id": "2112818584380739698", "url": "https://x.com/tetsuoai/status/2112818584380739698", "text": "Look Inside, end 200,000× smaller than a proton.\n\n• One shot. Zero cuts.\n• 40 worlds, each one inside the last.\n• 8.9 quintillion× zoom.\n• As one flat image: 1.5 × 10⁴⁴ pixels.\n• Printed at phone sharpness, 95 light years wide.\n• 16,423 frames. 34 billion pixels on screen.\n• The last frame is the first. It never ends.\n• The 41st world is the one you live in.\n\nAre you awake?", "name": "tetsuo", "handle": "tetsuoai", "avatar": "https://pbs.twimg.com/profile_images/2035289570598924288/kAOCyKpV_200x200.jpg", "likes": 297, "rts": 52, "replies": 55, "views": 12235, "ts": 1792570179, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112818350871158784/vid/avc1/1280x720/7vsfqqWpP1Ez-hnR.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112818350871158784/vid/avc1/1920x1080/lh_S1UiGbFU5f4U9.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112818350871158784/img/a0p6_HlWFWrKVj8V.jpg", "dur": 274}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 6.01, "thread": [], "tier": "must"}, {"id": "2112884146338975998", "url": "https://x.com/MollySOShea/status/2112884146338975998", "text": "Ken Griffin of Citadel questions the economics of the AI infrastructure boom:\n\n›What happens when GPU supply exceeds demand & pricing goes into free fall?\n\n›Are today's semiconductor margins sustainable? Are investors overestimating the useful life of GPUs?\n\n“Look, I think this market is actually experiencing people doing research.\n\nFor the couple of years, if you were on the thematic program of we're gonna spend hundreds of billions or a trillion dollars in data centers, we're gonna build compute at a scale never seen before, which companies in that story are choke points in supply chains that will have abnormally high margins? And who will be the big winners in this transformation?\n\nWill it be the Microsofts & AWSs who will be the gatekeepers to the foundational models? Like, who's going to earn the economic rents?\n\nBut in some sense, like, 'I'm just gonna buy them all. I'm gonna buy the hyperscalers, I'm gonna buy the chip, I'm gonna buy businesses that make things I've never even heard of 5 years ago in Korea and Taiwan & in Japan.'\n\nAnd now we're reaching a point where people are becoming more discerning.\n\nWe do realize that we are seeing extremely high margins in DRAM & MLCCs in areas where there are real supply constraints, but people are now starting to look out 2 years, 3 years. How long is this going to last?\n\nAnd in particular, I don't wanna be doom & gloom, but GPUs, like airlines, have a very low marginal cost to run.\n\nThe incremental seat on an airline that's not full, if you can sell that ticket for $20, you're making money in that seat.\n\nAnd that's one of the reasons that the airline industry is such a nightmare, is because the moment you have overcapacity, pricing goes into free fall.\n\nWe saw this actually with the telecom build-out back in 2000. We built more fiber than we had demand for, & the price of telecommunications just went straight down.\n\nIf we reach a point where the provisioning of GPUs exceeds demand for GPUs, marginal pricing will actually go into free fall.\n\nAnd that really upends all the investment assumptions that people are working with today.\n\nThat's issue number one.\n\nAnd issue number 2 is: \n\nI think people are taking a step back & saying, 'What is the useful life of a GPU?'\n\nRight here, right now, there's people that are earning extraordinary pricing on GPUs that are 5 or 6 years old.\n\nAnd so there's a growing set of concerns that I can't give the same capitalization rate or the same revenue models to year 7, 8, 9 of a chip in the future that maybe I was using 12 months ago.\n\nSo I think we're really grappling with just how far will this demand carry us in the marketplace.”", "name": "Molly O’Shea", "handle": "MollySOShea", "avatar": "https://pbs.twimg.com/profile_images/1673061505351450624/2A8YvQ2N_200x200.jpg", "likes": 294, "rts": 32, "replies": 37, "views": 60421, "ts": 1792585810, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112883148841164800/vid/avc1/1280x720/IcLoDJypFGLkmkr5.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112883148841164800/vid/avc1/1920x1080/F2YATy8QSNCTxTh-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112883148841164800/img/Qh7tMbk5CzXQxYWC.jpg", "dur": 195}], "quote": null, "reply_to": null, "cat": "Research & Safety", "score": 6.01, "thread": [], "tier": "must"}, {"id": "2112995956090454238", "url": "https://x.com/ericzakariasson/status/2112995956090454238", "text": "some pages ive been finding useful\n\n- launch burn-down lists\n- design docs i iterate on with @bot\n- morning briefs\n- what did i get done this week", "name": "eric zakariasson", "handle": "ericzakariasson", "avatar": "https://pbs.twimg.com/profile_images/1841151626456801283/HnXqy3TQ_200x200.jpg", "likes": 246, "rts": 9, "replies": 21, "views": 18534, "ts": 1792612468, "media": [], "quote": {"id": "2112992872857252082", "url": "https://x.com/bot/status/2112992872857252082", "text": "Grok Bot can now build reports, memos, and dashboards.\n\nAsk Bot for a page, then edit it together or have Bot keep it up to date.", "name": "Grok Bot", "handle": "bot", "avatar": "https://pbs.twimg.com/profile_images/2087219239275069440/KW6C403V_200x200.jpg", "likes": 7003, "rts": 520, "replies": 1047, "views": 1072745, "ts": 1792611733, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112992722529226752/vid/avc1/1280x720/CM_-XWr2v-MKSHHL.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112992722529226752/vid/avc1/1920x1080/Pj0Pze4xLpjvRJgG.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112992722529226752/img/3vCQwgTBFW-Svcnq.jpg", "dur": 27}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 6.0, "thread": [], "tier": "must"}, {"id": "2112801629720236509", "url": "https://x.com/ChrisGPT/status/2112801629720236509", "text": "Dario finally confirms Anthropic is:\n\n“\"Anthropic is over 5,000 people.\" They’re catching up to OAI.\n\nsome other quotes I enjoyed.\n\n“We likely sacrificed a significant chunk of a several-month model lead.” - speaking about mythos.\n\n\"I will have more to say soon about how we are going to further live our values in this moment of rapid change.\"\n\n\"We are nearing that point and that’s what’s driving some of our thinking about 'pacing.'\"", "name": "Chris", "handle": "ChrisGPT", "avatar": "https://pbs.twimg.com/profile_images/2046736394152812544/LfmDgg0I_200x200.jpg", "likes": 493, "rts": 14, "replies": 20, "views": 66131, "ts": 1792566137, "media": [], "quote": {"id": "2112732230124818891", "url": "https://x.com/DarioAmodei/status/2112732230124818891", "text": "Thank you for this, @_NathanCalvin. I appreciate and am a fan of the investigative work you’ve done on behalf of AI safety and believe your comments are coming from a constructive, honest place, and that it benefits the public to have people whose job is to scrutinize the actions of frontier AI companies. I think something would be wrong if companies of the size of Anthropic didn’t get harshly criticized basically every day; strong antibodies against corporate power are a healthy feature of a free society, and especially so when issues of the gravity of the one we’re facing are at play. I also do agree that some of the examples you cite were mistakes by Anthropic.\n\nThat said, I disagree with the thrust of your post. At the core, a good fraction of the things you criticize are consequences of Anthropic’s basic theory of change that we have held for many years. Our strategy has always been what I’ve called the “race to the top” — by showing how it’s possible to build the technology responsibly, we can raise the bar for the entire industry. The forces that drive the race to the top are hugely more effective if the company practicing them is at the frontier; that’s one lesson I’ve learned repeatedly. And looking at that strategy as a whole, I’m proud of our track record and stand by it.\n\nI believe that if we take a list of things that Anthropic did in the past year that were pro-safety and commercially costly to us, they far outweigh the list you’ve made, while at the same time I also disagree with some of the items on your list. Here are some things Anthropic has done, in the same period you’ve cited (the last year), which were very costly to us commercially while having strong safety benefits:\n\n1. We played a key role in SB53 (and other state laws), at a time when doing so was politically perilous to the company and AI regulation was very unpopular. We in fact argued for a stronger version of SB53 than was ultimately passed; there were a lot of stakeholders and we were not the limiting factor in the strength of the bill that was passed.\n\n2. We have very strong biological safeguards on our models, because we’ve seen concerning results in bio uplift trials and even seen and blocked potential attempts to misuse our models for bioweapons (as seen in our threat intelligence report from a few weeks ago). This is a very serious threat that we want to have zero tolerance for. But having very low false negatives means having significant false positives (despite months of effort on our part to improve the classifiers), enough so that biologists joke about how restrictive our classifiers are, and competitors sometimes sell against us by touting their more permissive bio capabilities. This has been very painful to us in an area where we care a lot about supporting an ecosystem of Claude users (biomedical science; and it is particularly frustrating to me as a biologist), but it’s the right thing to do and we intend to keep doing it.\n\n3. Similarly, we first had Mythos-class models in February but didn’t make them generally available until June (when we had stronger cyber safeguards in place). We only offered them to a limited set of partners in order to focus on cyberdefense. It would have been much more economically rational to simply release the model to everyone. We likely sacrificed a significant chunk of a several-month model lead. But because of this, many companies secured their cyber infrastructure before the deluge of widely available cyber-capable models. Of course there are ways it could have gone better or been run better, but this was what we were aiming to do.\n\n4. I advocated forcefully and publicly, in my essay Policy on the AI Exponential in June of this year, for the government to have the power to block model releases. Back then this was still outside or maybe on the edge of the Overton window, though I understand the window has moved since then. We were attacked intensely for this.\n\n5. I don’t want to re-ignite conflict, but the events of February 2026 are a strong example. It is clear that our public stance could have seriously damaged the company’s future.\n\n6. We’ve continued to advocate for export controls on chips and chipmaking equipment to China, because we think it allows democracies to negotiate from a position of strength on AI safety agreements. We’ve done this despite problems it’s created for us with industry partners who hold very different views and on whom we are very dependent.\n\n7. As far as I’m aware we were the first, and still only, frontier company to restrict the sale of AI services to PRC-controlled companies, including those operating through third countries (otherwise a major loophole). We’ve therefore forfeited significant short-term business to prevent fueling AI platforms and applications that would help the CCP’s military and intelligence services. We are also cracking down on distillation; generally, distillation is not a major threat to us commercially, but like chip exports it has concerning national security and safety implications, so we expend significant energy and company resources to address it.\n\n8. As you mentioned, we’ve put out a lot of reports, announcements, long model cards, public advocacy, etc, all trying to inform the public about the risks of AI. These involve a level of detail and effort that would be implausible for a purely profit-maximizing company.\n\n9. Just this week, we announced we were putting 5% (and possibly more over time) of the company into a public benefit fund.\n\nAll of these decisions came with very substantial costs to us. To be fair, those that involved holding back or restricting access to frontier capabilities also had a broader cost — for example, the public might otherwise have benefitted from faster progress in biology, so I am not saying that our decisions were without tradeoffs — but they were not driven by profit-seeking.\n\nFor each decision, you can come up with ulterior motives that could have driven us — I think it is a general truth that any decision, on any topic, can always be portrayed as a nefarious scheme. But most of those end up being pretty farfetched or don’t fully make sense if you actually examine them closely. For example, it is deeply implausible that it would be a shrewd business move to block a large swath of research biology in order to do the work ourselves and compete with our customers; we expect the benefit to the ecosystem to greatly exceed the work Anthropic does itself, and for the two to complement each other. It is not in Anthropic’s interest to be perceived as unfriendly to biologists. Our Life Sciences Verification Program, which gives vetted biology professionals access to our models, also refutes this idea. \n\nOf course, a different set of people will see this and make a different criticism: that Anthropic shouldn't be making decisions about who gets access to what in the first place. I agree, in the sense that ideally the government would be making these decisions, and that’s why we advocate for regulation. But for now we are forced to make them, and enabling bioterrorism isn’t a better option.\n\nI think that even if I conceded every item in your list, I would happily hold up mine next to it; I don’t think it’s a close call. That is of course partly subjective and different things are important to different people. Maybe one way you could object is that several of the items above relate to AI misuse and not loss-of-control; if you think the latter is much more important than the former, that might change your calculus. But this is not Anthropic’s view — we view both as serious issues. You can also disagree with our decisions, as many have, but they are consistent.\n\nBut I also disagree with at least some of your list. Several items don’t represent a deviation from Anthropic’s strategy or values at all, once we postulate the “race to the top” strategy that requires being a frontier AI company. Your items 1-4 are all simply examples of what it means to compete at the frontier, and we stand by them, both in the sense that they are transparently ordinary things to do as part of that strategy, and that we stand by the strategy as a whole. \n\nTo be fair, there are important questions worth confronting (and that we are confronting) about what to do when the AI-driven acceleration gets fast enough that it is hard for safety to keep up. We are nearing that point and that’s what’s driving some of our thinking about “pacing.” But 1-4 are actions taken before that point and should be perfectly expected based on Anthropic’s strategy as a company. Of course it is possible to disagree with that strategy, but that’s a more fundamental disagreement that you could have had any time over the last few years.\n\nI agree we could have handled your items 7, 8, and 9 better. All fall into the category of “rhetoric or policy communication that wasn’t carefully written or resulting from fast-changing circumstances not propagating from one team to another fast enough.” This kind of thing happens a lot in large organizations (Anthropic is over 5,000 people), and doesn’t even necessarily represent a failure or mistake of any single person. I am of course the CEO, and I take responsibility. The volume of communication from Anthropic is enormous and if these are the worst examples, I think we’re frankly doing pretty well, though I will continue to work hard to make sure we do even better.\n\nYour 5th item (the change to our RSP) is the most substantive item, and people can debate this, but I think that the old, more rigid RSP created a lot of situations where we were technically required to do something that required a lot of effort but in retrospect wasn’t very important for safety, as well as not covering some of the most important things. Our current RSP’s focus on transparency brought things like risk reports and roadmaps, and its emphasis on independent external review laid the groundwork for even more intensive embedded evaluation, all of which I think have been valuable in driving a race to the top. In the original announcement in September 2023, we described the RSP as an “early iteration that we [would] build on” and said that “rapid iteration…will almost certainly be necessary.” I understand that changing plans is always a move that creates justifiable scrutiny — I just don’t think we ever represented that we wouldn’t do so.\n\nRelating to your 6th item (having an FCF in addition to our RSP), I know our intent is to meet the letter and spirit of our regulatory obligations (via our FCF) while also remaining able to experiment with more novel approaches to risk management that go beyond what the law currently requires (via our RSP). I promise to look into it further, as it’s a complex issue and it is possible we are not weighing the considerations in the right way.\n\nOverall, although Anthropic has made plenty of mistakes as an organization — including some of the items on your list — I feel that we have repeatedly taken serious and substantive actions counter to our bottom line and that there is a significant negativity bias distorting assessments like the one you are making above. We’ll always try to do better but, again, I am extremely proud of our track record and stand by it. I will have more to say soon about how we are going to further live our values in this moment of rapid change.", "name": "Dario Amodei", "handle": "DarioAmodei", "avatar": "https://pbs.twimg.com/profile_images/2015835742577012736/uOwdzrEz_200x200.jpg", "likes": 3925, "rts": 302, "replies": 703, "views": 1350149, "ts": 1792549590, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.99, "thread": [], "tier": "must"}, {"id": "2112949457491005543", "url": "https://x.com/abhijeet_dipke/status/2112949457491005543", "text": "Boys have a message\n\nGyanu must go!", "name": "Abhijeet Dipke", "handle": "abhijeet_dipke", "avatar": "https://pbs.twimg.com/profile_images/2080997334398140416/rPBE_IDp_200x200.jpg", "likes": 32292, "rts": 6185, "replies": 2860, "views": 890268, "ts": 1792601382, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112949321406799872/vid/avc1/480x852/Mcx_N8uw-2BCNlFD.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112949321406799872/vid/avc1/576x1024/xp2hr4g3ci4vuWmS.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112949321406799872/img/HmLpr6oB6kQsnGHF.jpg", "dur": 7}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.99, "thread": [], "tier": "must"}, {"id": "2112868500092097009", "url": "https://x.com/thegreatest_sv/status/2112868500092097009", "text": "Anthropic is furious: this secret tool can replicate any existing app x10 faster for free\n\nthere's an open-source tool with 352k stars on GitHub that lets an AI agent take apart any app you have on your machine and explain exactly how a feature works. no source code needed.\n\nit's called REA. Reverse Engineer Anything.\n\none line:\n\nnpx rea-agents setup\n\nthen you just ask Claude Code:\n\n\"Understand how search works in the Notes app, show me the evidence, and build a similar feature for my project.\"\n\nand it does it.\n\n-> native binaries, through Ghidra, Hopper or IDA\n-> JavaScript and Electron apps\n-> .NET apps\n-> websites\n\nit runs locally. it shows its evidence. then it writes the code.\n\nthat feature your team spent 8 months on? someone's agent can read how it works over lunch.\n\nso let's be honest about what this means:\n\nyour moat was never the code. it was that copying you took effort.\n\nthat effort just went to zero.\n\nthe only things left that can't be cloned: your users, your speed, and your taste.\n\nand if your product dies because someone could see how it works, it was already dead.\n\nthe repo is below. founders, you're going to hate this one \nhttps://github.com/morluto/rea\n\nsave, share, and try later", "name": "kiosa", "handle": "thegreatest_sv", "avatar": "https://pbs.twimg.com/profile_images/2049557081502752768/gymBLMZ8_200x200.jpg", "likes": 255, "rts": 54, "replies": 19, "views": 19869, "ts": 1792582080, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112860595691159552/vid/avc1/720x900/WhYUZ3bqMaGNF8jH.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112860595691159552/vid/avc1/1080x1350/_pPFgHn0bb6IOGq-.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112860595691159552/img/wNvU96aAQBkhWLfE.jpg", "dur": 25}], "quote": {"id": "2052035306094817436", "url": "https://x.com/thegreatest_sv/status/2052035306094817436", "text": "", "name": "kiosa", "handle": "thegreatest_sv", "avatar": "https://pbs.twimg.com/profile_images/2049557081502752768/gymBLMZ8_200x200.jpg", "likes": 52, "rts": 13, "replies": 2, "views": 156167, "ts": 1778078316, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.98, "thread": [], "tier": "must"}, {"id": "2113015582488728040", "url": "https://x.com/chetaslua/status/2113015582488728040", "text": "Some unreleased model must be having fun this week 😭\n\nPHP: critical RCE, and the patch may be incomplete\nNode.js: urgent RCE patches\nGitLab: CVSS 10.0 unauthenticated RCE, 12 years of releases\nLiteLLM 1.107.0: shipped with credential-stealing malware\nOpenCode Console: leaked users’ API keys\neMudhra CA: private key was literally 4", "name": "Chetaslua", "handle": "chetaslua", "avatar": "https://pbs.twimg.com/profile_images/1926364057004646400/z3oD9QyB_200x200.jpg", "likes": 211, "rts": 14, "replies": 13, "views": 11127, "ts": 1792617147, "media": [], "quote": {"id": "2112981939984671090", "url": "https://x.com/TheHackersNews/status/2112981939984671090", "text": "🚨 CRITICAL: GitLab flaw (CVSS 10.0) affects 12 years of releases.\n\nCVE-2026-110264 could allow unauthenticated remote code execution on self-managed servers.\n\nRead - https://thehackernews.com/2026/10/critical-gitlab-flaw-cvss-100-could.html", "name": "The Hacker News", "handle": "TheHackersNews", "avatar": "https://pbs.twimg.com/profile_images/1597647879811657728/FLgHrLHy_200x200.jpg", "likes": 11295, "rts": 2432, "replies": 205, "views": 2284404, "ts": 1792609126, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.97, "thread": [], "tier": "must"}, {"id": "2112968064451084798", "url": "https://x.com/orcdev/status/2112968064451084798", "text": "I joined @neondatabase 💚\n\nI'll be doing DX and leading open source at Neon. Also I guess I'm their mascot now. 😂\n\nOrcs are green. Neon is green. It was meant to be. 🟢\n\nI love Neon, and I love the team even more. This move just made sense.\n\nThe channel stays OrcDev. Same orc. Same Horde.\n\nFollow along. Things are about to get interesting 👀", "name": "OrcDev", "handle": "orcdev", "avatar": "https://pbs.twimg.com/profile_images/1756766826736893952/6Gvg6jha_200x200.jpg", "likes": 228, "rts": 7, "replies": 36, "views": 7477, "ts": 1792605818, "media": [], "quote": {"id": "2112912889195417846", "url": "https://x.com/orcdev/status/2112912889195417846", "text": "It's official.\n\nMy new chapter. 🟢⚔️", "name": "OrcDev", "handle": "orcdev", "avatar": "https://pbs.twimg.com/profile_images/1756766826736893952/6Gvg6jha_200x200.jpg", "likes": 404, "rts": 12, "replies": 151, "views": 23696, "ts": 1792592663, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112911821262696448/vid/avc1/1280x720/2qMrkmkqEjWyYGID.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112911821262696448/vid/avc1/3840x2160/pzEwWSZB5G_Ht-84.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112911821262696448/img/xmN3vz0cN5LO8TzW.jpg", "dur": 197}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.97, "thread": [], "tier": "must"}, {"id": "2113017379240480905", "url": "https://x.com/jauneclaude/status/2113017379240480905", "text": "Has anyone noticed Claude Duet get dumber recently?\n\nIt messes up in even the simplest of tasks and 80% of my usage quota is gone in a single prompt", "name": "Jean-Claude", "handle": "jauneclaude", "avatar": "https://pbs.twimg.com/profile_images/2110727773585362944/slTqEPfW_200x200.jpg", "likes": 181, "rts": 2, "replies": 45, "views": 29549, "ts": 1792617575, "media": [], "quote": {"id": "2112984664256241837", "url": "https://x.com/claudeai/status/2112984664256241837", "text": "We’re opening a research preview of Claude Duet, a new app where Claude works as a proactive agent.\n\nIt comes to you with what needs your attention, completes tasks you ask of it, keeps working when you step away, and checks with you before it acts on your behalf.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 43214, "rts": 3270, "replies": 1714, "views": 5528053, "ts": 1792609775, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVLUnMDWsAAn7Pw.png", "dur": 100}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.97, "thread": [], "tier": "must"}, {"id": "2112907892995264580", "url": "https://x.com/sakhil_ai/status/2112907892995264580", "text": "ANTHROPIC RELEASED CLAUDE SONNET 5.5\n\nA new model built around code, agentic tasks and everyday work\n\nWhat's new:\n\n> 30%+ faster than Sonnet 5\n> up to 30% cheaper per task thanks to lower token usage\n> 70.6% on Terminal-Bench 4.0 versus 10.3% for Sonnet 5\n> 55.5% on CursorBench 4.0, about 2 points below Opus 5.5\n> on GDPval-AA the model nearly matched Opus 5.5\n> better at long tasks, images, documents, spreadsheets and presentations\n\nThe most notable jump is in coding. Anthropic says Sonnet 5.5 gets through codebases faster, makes fewer tool calls and spends fewer steps completing tasks\n\nAPI pricing:\n\n> $2 / 1M input tokens\n> $10 / 1M output tokens\n> $0.20 / 1M cache reads\n\nThe model is already available in Claude, the API, AWS, Google Cloud and Azure\n\nAPI ID: claude-sonnet-5-5\n\nSave this. You’ll definitely need some of these later! 🔖\n\nLike👍\nComment 💬\"Sonnet\"\nRetweet 🔃\nFollow👤\n@sakhil_ai\n\nfor more useful websites, AI tools & tech resources.\n\nI will DM ✉️for you", "name": "Sakhil Khan", "handle": "sakhil_ai", "avatar": "https://pbs.twimg.com/profile_images/1942942812879659008/fElrNqb__200x200.jpg", "likes": 94, "rts": 70, "replies": 38, "views": 1624, "ts": 1792591472, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112907860044898304/vid/avc1/480x604/voWvaNuu6jfLfGej.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112907860044898304/vid/avc1/720x908/7DjZ-haziThz0ESa.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112907860044898304/img/w-9miR7P-4l2UPj9.jpg", "dur": 30}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.96, "thread": [], "tier": "must"}, {"id": "2112985698894745918", "url": "https://x.com/rryssf/status/2112985698894745918", "text": "\"second brain porn\" goes on", "name": "Robert Youssef", "handle": "rryssf", "avatar": "https://pbs.twimg.com/profile_images/1949976517913513985/98Qk6qo5_200x200.jpg", "likes": 265, "rts": 8, "replies": 4, "views": 29406, "ts": 1792610022, "media": [], "quote": {"id": "2112963898739765633", "url": "https://x.com/supermemory/status/2112963898739765633", "text": "Introducing the supermemory memory graph\n\nevery document becomes atomic facts, and dreaming keeps building the graph in the background\n\n- extracting facts\n- linking related memories\n- resolving updates, the old version stays as history\n\nget one for yourself in the console ↓", "name": "supermemory", "handle": "supermemory", "avatar": "https://pbs.twimg.com/profile_images/2097722228054048768/kw2Eo329_200x200.jpg", "likes": 603, "rts": 40, "replies": 28, "views": 76796, "ts": 1792604825, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112963859040665600/vid/avc1/1280x720/bB--nx7J5z55p624.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112963859040665600/vid/avc1/1920x1080/NSvunDZReBWcWLMs.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112963859040665600/img/yvZV5ANR22aEFsit.jpg", "dur": 41}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.96, "thread": [], "tier": "must"}, {"id": "2112912588027650182", "url": "https://x.com/Mr_Salio/status/2112912588027650182", "text": "🚨 Opus 5.5 (Launch) vs Opus 5.5 ( Now)\n\nSame prompt Same effort\n\nThe usage: They nerfed The usage limits Hard it's are draining MUCH faster \n\nthe quality: it feels similar no big change but some time you feel little laziness but other than that it's the same\n\nWhy do they nerfed the limits?", "name": "Salio", "handle": "Mr_Salio", "avatar": "https://pbs.twimg.com/profile_images/2027630388403965952/mgrd9d6O_200x200.jpg", "likes": 253, "rts": 8, "replies": 49, "views": 49644, "ts": 1792592591, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112912506310057984/vid/avc1/1280x720/NllsMOtL9fJRy1nJ.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112912506310057984/vid/avc1/1920x1080/iY_Kfot5zJ5Biemc.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112912506310057984/img/vz76UZIQE0FIZYsO.jpg", "dur": 45}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.96, "thread": [], "tier": "must"}, {"id": "2112965464565731437", "url": "https://x.com/irongiantXBT/status/2112965464565731437", "text": "this is the most underrated grok bot setup right now\n\n1 router + 4 specialist agents - no polling, no wasted runs, nothing fires until something actually needs it\n\ni ran the numbers before switching - a routine every 5 minutes costs 12x more than hourly - $397/mo vs $33 for the same result\n\n→ webhooks, slack, github and email all feed one router\n→ most events get dropped on purpose - zero wasted runs\n→ 4 specialist agents spin up only when there's real work\n→ risky actions pause at a draft before they reach you\n\nstop polling every 5 minutes - let events drive your agents\n\nhere's the exact setup, send it to your grok bot 👇", "name": "Iron Giant", "handle": "irongiantXBT", "avatar": "https://pbs.twimg.com/profile_images/2073301331738046464/UuZ4Un9H_200x200.jpg", "likes": 218, "rts": 16, "replies": 27, "views": 30020, "ts": 1792605198, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112965364539858944/vid/avc1/720x720/-I1jYtRSf9oXqaqR.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112965364539858944/vid/avc1/1080x1080/ByIkhn_9Yg5n9kfr.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112965364539858944/img/PnYbfxxWF3D0uVb6.jpg", "dur": 24}], "quote": {"id": "2109293672495784029", "url": "https://x.com/irongiantXBT/status/2109293672495784029", "text": "https://x.com/i/article/2109287151040888832", "name": "Iron Giant", "handle": "irongiantXBT", "avatar": "https://pbs.twimg.com/profile_images/2073301331738046464/UuZ4Un9H_200x200.jpg", "likes": 343, "rts": 49, "replies": 35, "views": 505489, "ts": 1791729774, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.96, "thread": [], "tier": "must"}, {"id": "2112782970474139927", "url": "https://x.com/Teknium/status/2112782970474139927", "text": "More game development powers for your Hermes Agent!", "name": "Teknium 🪽", "handle": "Teknium", "avatar": "https://pbs.twimg.com/profile_images/1642401912648777728/2KFikPsE_200x200.jpg", "likes": 413, "rts": 28, "replies": 26, "views": 19613, "ts": 1792561688, "media": [], "quote": {"id": "2112781937303851341", "url": "https://x.com/DecruxR/status/2112781937303851341", "text": "Asked my hermes agent @NousResearch  for a game.\n\nIt made sprites, sound, music, 3D, and a playable Godot build. Then it played the build and caught a crash.\n\n9 tools, 10 skills, offline by default, zero core changes.\n\n@Teknium \nhttps://github.com/DECRUX9812/hermes-plugin-gameforge", "name": "HotDawg", "handle": "DecruxR", "avatar": "https://pbs.twimg.com/profile_images/2101584132044369920/fqPKzLR5_200x200.jpg", "likes": 115, "rts": 10, "replies": 14, "views": 19008, "ts": 1792561442, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112781664468541440/vid/avc1/1280x720/rM_iwg9HqZu2HsIW.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112781664468541440/vid/avc1/1920x1080/_hxdehOUmdXneylo.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112781664468541440/img/-UfX7XGYCVxC4mF5.jpg", "dur": 60}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.95, "thread": [], "tier": "must"}, {"id": "2112955969676497300", "url": "https://x.com/ornith_/status/2112955969676497300", "text": "🐦 Ornith-1.5, including the recent 122B one, are built upon Ornith-1.0, which was developed on top of Qwen3.5 @Alibaba_Qwen with additional continued pretraining, mid-training, and post-training.\n\n🫡 Thanks to the open-weight community! \n\n👀 Please feel free to build your own projects or model variants on top of Ornith.", "name": "Ornith", "handle": "ornith_", "avatar": "https://pbs.twimg.com/profile_images/2067467120544456704/qYuod4O1_200x200.jpg", "likes": 222, "rts": 18, "replies": 20, "views": 7355, "ts": 1792602934, "media": [], "quote": {"id": "2090258105682854390", "url": "https://x.com/ornith_/status/2090258105682854390", "text": "🐦Ornith-1.5 is built upon Ornith-1.0, which was developed on top of Qwen3.5 @Alibaba_Qwen with additional continued pretraining, mid-training, and post-training.\n\n🫡Thanks to the open-weight community! \n\n👀We are happy and welcome more projects/model variants built on Ornith.", "name": "Ornith", "handle": "ornith_", "avatar": "https://pbs.twimg.com/profile_images/2067467120544456704/qYuod4O1_200x200.jpg", "likes": 473, "rts": 31, "replies": 21, "views": 28167, "ts": 1787191342, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.95, "thread": [], "tier": "must"}, {"id": "2113004440424714275", "url": "https://x.com/eliebakouch/status/2113004440424714275", "text": "i find it really sad that X is becoming a pay to win platform and that even \"good\" releases are going through these fully slop/fake campaigns to get traction\n\ni'm also pretty sure there is very shady stuff where they are boosting each other's posts with bot farms and more. would be great to investigate here @elonmusk and make sure the algorithm doesn't push their posts, you can very easily cluster that if you look at each release and the accounts amplifying 🙏\n\n(not a dunk on recursive, recently a lot of people are doing that unfo and it's definitely working, posts often get over ~1M views)", "name": "elie", "handle": "eliebakouch", "avatar": "https://pbs.twimg.com/profile_images/1745893660099592193/MmYemsw6_200x200.jpg", "likes": 200, "rts": 4, "replies": 29, "views": 16729, "ts": 1792614490, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVLlJT3X0AA4U0n.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVLlJxcXYAAQHyD.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVLlKPsXIAAP8Yj.jpg?name=orig"}, {"type": "photo", "url": "https://pbs.twimg.com/media/HVLlKgDWgAAB38i.jpg?name=orig"}], "quote": {"id": "2112944385415426249", "url": "https://x.com/RichardSocher/status/2112944385415426249", "text": "Introducing Flint, @Recursive_SI’s first model: a fast local coding model built with our automated research system, the Eureka Machine.\n\n• Best-in-class fast local coding\n• Up to 2x faster than comparable models: 125+ tokens/sec on a MacBook Pro, 150+ on RTX Spark\n• Built from scratch in under 4 months\n\nPrivate, unmetered intelligence on your own machine. Open weights available now on @huggingface, run it locally on your favorite framework or try it for free on @opencode or @pidotdev.", "name": "Richard Socher", "handle": "RichardSocher", "avatar": "https://pbs.twimg.com/profile_images/1232361282759610368/YYxndVmI_200x200.jpg", "likes": 6094, "rts": 643, "replies": 485, "views": 2499045, "ts": 1792600172, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112941750809419776/vid/avc1/1280x720/ljeVLZeytT--ckEJ.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112941750809419776/vid/avc1/3840x2160/OjycwsU9wNo0PMbi.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112941750809419776/img/MJaHRrNTo-Kg92Pb.jpg", "dur": 161}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.94, "thread": [], "tier": "must"}, {"id": "2112885588462276789", "url": "https://x.com/ScottyBeamIO/status/2112885588462276789", "text": "WTF, THIS IS PURE GOLD AND IT SHOULDN’T BE FREE.\n\nTHE GROK BOT TEAM JUST DROPPED 54 READY-MADE SETUPS YOU CAN START USING TODAY.\n\nNo prompt engineering. No building from scratch. You pick a bot, add it, and it gets to work.\n\nHere’s what’s inside:\n\n→ SALES: Outbound Prospecting, Signal Prospector, Sales Call Coach, Deal Inspector, Pipeline Pulse. They find leads, draft first messages, score your calls and flag risky deals.\n\n→ ENGINEERING: Startup QA Bot tests your product every weekday, Nightly Audit Engineer ships a cleanup PR every night, Proto Bot turns ideas into working prototypes.\n\n→ DESIGN: figma bro turns Figma frames into build specs, Critiquito gives ranked design critiques, Video Editor cuts talking-head videos from raw footage.\n\n→ MARKETING: SEO & AEO Desk, AI Search Visibility, Stalk Bot for watching competitors, Ad Spend Watch before your budget burns.\n\n→ OPS: Executive Assistant, Recruiting Coordinator, Haggle Bot that finds SaaS savings and drafts counteroffers for you.\n\nEach one has a clear job, an author behind it and a single page where you add it in a few clicks.\n\nAnd this is the part I like most.\n\nThese aren’t random templates from the internet. They’re built and tested by the people who make Grok Bot. They know exactly how the product works, what it does well and where it breaks.\n\nSo instead of spending a week tuning your own setup, you start with something that already works and adapt it to you.\n\nThat’s the fastest way to get real value out of Grok Bot right now.\n\nBookmark this so you have all 54 in one place.\n\nAnd if you want to know what else changed, I broke down the biggest recent Grok Bot updates in my article below ↓", "name": "SCOTTY BEAM", "handle": "ScottyBeamIO", "avatar": "https://pbs.twimg.com/profile_images/2029514153656721409/27fG1cCf_200x200.jpg", "likes": 245, "rts": 32, "replies": 20, "views": 16951, "ts": 1792586154, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112885444924891136/vid/avc1/720x900/BHDinMEYsVYo9ff5.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112885444924891136/vid/avc1/1080x1350/xH66_1X3aGxDjaIg.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112885444924891136/img/_Ek9m_EoePTn-VsY.jpg", "dur": 30}], "quote": {"id": "2108258293005316298", "url": "https://x.com/ScottyBeamIO/status/2108258293005316298", "text": "Grok Bot just got a MASSIVE upgrade – starting at $20/month.\n\nIt's own email. Smarter agents. Better coding tools. Tasks straight from X.\n\nSet it up once. Give it a goal. Let it keep working while you sleep. https://x.com/i/article/2108171813201080320", "name": "SCOTTY BEAM", "handle": "ScottyBeamIO", "avatar": "https://pbs.twimg.com/profile_images/2029514153656721409/27fG1cCf_200x200.jpg", "likes": 238, "rts": 22, "replies": 21, "views": 152597, "ts": 1791482921, "media": [], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.93, "thread": [], "tier": "must"}, {"id": "2113035695337992697", "url": "https://x.com/ClaudeCodeLog/status/2113035695337992697", "text": "Claude Code 2.1.307 has been released.\n\n43 CLI changes, 1 system prompt change\n\nHighlights:\n• Added /claude-api api-version to switch Claude API code to 2026-10-21, enabling updated API behavior\n• Stop double HTTP MCP sends on disconnect; only idempotent/read-only tools retried to avoid duplicates\n• The /clear command now makes cleared conversations persist across restarts, preventing them from reappearing\n\nFull details are in thread ↓", "name": "Claude Code Changelog", "handle": "ClaudeCodeLog", "avatar": "https://pbs.twimg.com/profile_images/2024922567320997889/1KnSSnCQ_200x200.jpg", "likes": 176, "rts": 8, "replies": 18, "views": 15878, "ts": 1792621942, "media": [{"type": "video", "url": "https://video.twimg.com/ext_tw_video/2113035666581831680/pu/vid/avc1/640x360/NRAgTrSrZGWfqKlL.mp4?tag=12", "hd": "https://video.twimg.com/ext_tw_video/2113035666581831680/pu/vid/avc1/1280x720/w454xTjSCOso39UH.mp4?tag=12", "thumb": "https://pbs.twimg.com/ext_tw_video_thumb/2113035666581831680/pu/img/u25i5sMyUjzR3Bqx.jpg", "dur": 42}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.93, "thread": [], "tier": "must"}, {"id": "2113089279077617806", "url": "https://x.com/RobertJBye/status/2113089279077617806", "text": "The proactive agent you’ve been waiting for!", "name": "Robert Bye", "handle": "RobertJBye", "avatar": "https://pbs.twimg.com/profile_images/2001121836910682112/jqwksbXH_200x200.jpg", "likes": 153, "rts": 1, "replies": 21, "views": 4162, "ts": 1792634718, "media": [], "quote": {"id": "2112984664256241837", "url": "https://x.com/claudeai/status/2112984664256241837", "text": "We’re opening a research preview of Claude Duet, a new app where Claude works as a proactive agent.\n\nIt comes to you with what needs your attention, completes tasks you ask of it, keeps working when you step away, and checks with you before it acts on your behalf.", "name": "Claude", "handle": "claudeai", "avatar": "https://pbs.twimg.com/profile_images/1950950107937185792/QOfEjFoJ_200x200.jpg", "likes": 43199, "rts": 3269, "replies": 1713, "views": 5525351, "ts": 1792609775, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112982862186106880/vid/avc1/640x360/L7zosiEUW76tqYr-.mp4?tag=29", "thumb": "https://pbs.twimg.com/media/HVLUnMDWsAAn7Pw.png", "dur": 100}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.93, "thread": [], "tier": "must"}, {"id": "2113032869048442925", "url": "https://x.com/Sai60012/status/2113032869048442925", "text": "OM HARI NARAYAN VASUDEVAYA NAMO ⚜️🙏\n\n🕉️\nH\nA\nR\nI\n\nN\nA\nR\nA\nY\nA\nN\n🕉️\nH\nA\nR\nI\n\nN\nA\nR\nA\nY\nA\nN  \n🕉️\nJAY HARI NARAYAN  \n🕉️\nJ\nA\nY\nH\nA\nR\nI\n\nN\nA\nR\nA\nY\nA\nN \n🕉️\nJ\nA\nY\nH\nA\nR\nI\n\nN\nA\nR\nA\nY\nA\nN  \n🕉️\n\rHARI\rNARAYAN NAMO BHAGAVTE VASUDEVAYA ⚜️ @grok", "name": "🌺Sai Fan", "handle": "Sai60012", "avatar": "https://pbs.twimg.com/profile_images/2108116778903867392/AxlXJw8l_200x200.jpg", "likes": 108, "rts": 34, "replies": 13, "views": 8358, "ts": 1792621268, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2113032835493933056/vid/avc1/360x640/TnQMjapbM7YjRsE5.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2113032835493933056/vid/avc1/360x640/TnQMjapbM7YjRsE5.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2113032835493933056/img/X7MZ7IPso6jX51PF.jpg", "dur": 32}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.92, "thread": [], "tier": "must"}, {"id": "2112797041092956524", "url": "https://x.com/ZelenskyyUa/status/2112797041092956524", "text": "Of course, we are not losing this war. But we are losing people. Because of the Russian attacks, we're losing people and time. It's such a pity, because our children don't have a real life and childhood. Not only children, but all people. That's why we need to end this war as quickly as possible. I hope that our partners, Americans and Europeans, will help us. God bless, our strong soldiers stay strong on the battlefield. It helps me stay strong during any kind of negotiations.", "name": "Volodymyr Zelenskyy / Володимир Зеленський", "handle": "ZelenskyyUa", "avatar": "https://pbs.twimg.com/profile_images/1585550046740848642/OpGKpqx9_200x200.jpg", "likes": 44690, "rts": 7631, "replies": 4710, "views": 1997507, "ts": 1792565043, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112796140009553920/vid/avc1/1280x720/WWiRXDX_SxrDI7v1.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112796140009553920/vid/avc1/1920x1080/6bvMsC1C--Sch_JI.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112796140009553920/img/hgJ1AaBymJlTL2VG.jpg", "dur": 41}], "quote": null, "reply_to": null, "cat": "Politics & World", "score": 5.91, "thread": [], "tier": "must"}, {"id": "2112854462708519013", "url": "https://x.com/NVIDIARobotics/status/2112854462708519013", "text": "NVIDIA announces new Isaac tools for agents as Agile Robots unveils Agile ONE SN, a reference humanoid for robotics research. 🦾\n\nBuilt on NVIDIA Isaac GR00T and powered by Jetson Thor, Agile ONE SN gives researchers and developers an integrated platform to develop, train and validate humanoid skills.\n\nThe Isaac expansion also introduces new datasets, a runtime, and robot learning framework updates to accelerate development from data to deployment.\n\nRead the #NVIDIAGTC announcement: https://nvidianews.nvidia.com/news/nvidia-advances-isaac-platform-for-general-purpose-robotics-with-new-reference-humanoid-frameworks-simulation-pipelines-and-data?ncid=so-twit-568062-vt48", "name": "NVIDIA Robotics", "handle": "NVIDIARobotics", "avatar": "https://pbs.twimg.com/profile_images/1864439831335718915/WJ2VocNK_200x200.jpg", "likes": 250, "rts": 38, "replies": 20, "views": 43935, "ts": 1792578733, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112854439610499072/vid/avc1/640x360/pjIkgur5oeZmu6kv.mp4?tag=16", "hd": "https://video.twimg.com/amplify_video/2112854439610499072/vid/avc1/1280x720/S7fXaAcIzmuujwfQ.mp4?tag=16", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112854439610499072/img/2xyMnvYK-EwIfP9r.jpg", "dur": 13}], "quote": null, "reply_to": null, "cat": "Research & Safety", "score": 5.91, "thread": [], "tier": "must"}, {"id": "2112959892130877533", "url": "https://x.com/alxshp/status/2112959892130877533", "text": "16.6 MB RAM vs. 70 KB. 🤯\n\n1,000 databases. ONE PGX process. 🐘\n\nOne idle PostgreSQL server: 16.6 MB. \nVS\nOne idle PGX database: just 70 KB!!\n\nMeasured on a 4 vCPU / 8 GB VM:\n\n⚡ 128–155 MB RAM - 1,000 untouched DBs \n⚡ 213 MB - all queried once \n⚡ 283 MB - 100 active databases \n⚡ 0.33–0.43% of one CPU core at idle\n\nThis is why we built PGX. 🐘\n\nEvery AI agent deserves its own database. Not its own server.\n\nhttps://x.com/alxshp/status/2112579971952910540", "name": "alex shapalov", "handle": "alxshp", "avatar": "https://pbs.twimg.com/profile_images/1978552796988493824/lEtPOGNq_200x200.jpg", "likes": 211, "rts": 16, "replies": 13, "views": 10403, "ts": 1792603869, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112958929437364224/vid/avc1/948x720/jT_6pLVdsX9SxC0i.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112958929437364224/vid/avc1/2844x2160/X6iXksLMynP8eGOt.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112958929437364224/img/Pa2Hi3AtkcRCDMDe.jpg", "dur": 18}], "quote": {"id": "2112579971952910540", "url": "https://x.com/alxshp/status/2112579971952910540", "text": "🚨Introducing a new database: PGX 🐘\n\nPostgres for AI agents. In Rust.  http://pgx.dev \n\nOne runtime. Thousands of Postgres databases.\n\n⚡ Up to 100× less idle memory\n⚡ 1,000 databases in just 659 MB RAM\n⚡ Clone a 674 MB database in 85 ms\n⚡ ~0.7 MB per idle database\n\nRUST. OPEN SOURCE. FREE.\n\nNo containers per database.\nNo heavyweight instances.\nNo production baggage.\n\nReal Postgres. Built to be disposable.\n\nhttps://x.com/alxshp/status/2110049413070831817", "name": "alex shapalov", "handle": "alxshp", "avatar": "https://pbs.twimg.com/profile_images/1978552796988493824/lEtPOGNq_200x200.jpg", "likes": 1117, "rts": 98, "replies": 95, "views": 94106, "ts": 1792513289, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112372069308694529/vid/avc1/1190x720/6WoEAoIuaIto8rEy.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112372069308694529/vid/avc1/3572x2160/RJhhw9-cEEJh3GeA.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112372069308694529/img/n5MlTVsknCrF5wOq.jpg", "dur": 15}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Tools & Agents", "score": 5.91, "thread": [], "tier": "must"}, {"id": "2112967131088470507", "url": "https://x.com/TeardropEmily/status/2112967131088470507", "text": "Welcome to the internet.", "name": "🏳️‍⚧️🤍Emmy🤍🏳️‍⚧️", "handle": "TeardropEmily", "avatar": "https://pbs.twimg.com/profile_images/1941878248364740608/4Ho3sa5D_200x200.jpg", "likes": 33923, "rts": 3676, "replies": 108, "views": 464570, "ts": 1792605595, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVLEUFxWsAAxmfD.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.91, "thread": [], "tier": "must"}, {"id": "2113038595854623029", "url": "https://x.com/reflection_ai/status/2113038595854623029", "text": "We teamed up with @huggingface to give away $20,000 to anyone who's building with Beam 🤗 \n\nUse Beam for any project - make a demo or a dataset, benchmark the model, create an RL environment - and comment your link in the model's repo page by Monday, November 2. \n\nWe choose the winners. Winners choose cash or credits. Claim $25 in Hugging Face credits to build with Beam and enter the competition 👇 \n\nhttps://huggingface.co/reflection/Beam-1.0-501B-A23B/discussions/5", "name": "Reflection", "handle": "reflection_ai", "avatar": "https://pbs.twimg.com/profile_images/2107189477575696385/id98cuOX_200x200.jpg", "likes": 151, "rts": 18, "replies": 10, "views": 21970, "ts": 1792622634, "media": [], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.91, "thread": [], "tier": "must"}, {"id": "2112953857718501769", "url": "https://x.com/Ace8trriger/status/2112953857718501769", "text": "PHPの助弱性で日本にサーバー攻撃が集中…\n\n分かりやすく言うとサマーウォーズ状態。", "name": "田口 タツヤ/株式会社サガシテ代表", "handle": "Ace8trriger", "avatar": "https://pbs.twimg.com/profile_images/2002353080613081088/aB46nmHO_200x200.jpg", "likes": 36429, "rts": 3449, "replies": 189, "views": 2646053, "ts": 1792602431, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112953829444714496/vid/avc1/1280x720/4Cw5Q6CvdE6hDroF.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112953829444714496/vid/avc1/1920x1080/ufAJdQgQFMCXNMKu.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112953829444714496/img/otKuX8cdBm6sTI-q.jpg", "dur": 12}], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.91, "thread": [], "tier": "must"}, {"id": "2112971691966267827", "url": "https://x.com/thtbee_/status/2112971691966267827", "text": "Gemini 4 Carbon - A Mechanical bee!\n\nDid my mechanical Bee test with Carbon.. It's actually better than Argon on the overall polish and detailing..\n\nIt nailed the bee's waggle dance which they do in a figure 8 pattern and the wing movement!\n\nSee how Argon did in the quoted post!", "name": "Bee", "handle": "thtbee_", "avatar": "https://pbs.twimg.com/profile_images/2083983655387742208/J6MwCk4b_200x200.jpg", "likes": 193, "rts": 19, "replies": 13, "views": 4895, "ts": 1792606683, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112971150624276481/vid/avc1/1280x720/0XHC_bRWo6fn0mbp.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112971150624276481/vid/avc1/1920x1080/hhSxvgmxs-aizaBS.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112971150624276481/img/Iko3l_moe4dURG6j.jpg", "dur": 37}], "quote": {"id": "2105320019920080921", "url": "https://x.com/thtbee_/status/2105320019920080921", "text": "Gemini 4 Pro has surprised again - A mechanical Bee :)\n\nIt has improved a lot since the last checkpoint in terms of design taste and prompt adherence..\n\nI have a few more outputs that I'll be sharing soon..\n\nI'd been trying endlessly since the new checkpoint dropped, and finally got it a couple of times today between 4-5 AM for some outputs.. Not able to get it since, so it might have been pulled off again.. Please confirm if anyone else can get it..", "name": "Bee", "handle": "thtbee_", "avatar": "https://pbs.twimg.com/profile_images/2083983655387742208/J6MwCk4b_200x200.jpg", "likes": 1507, "rts": 79, "replies": 80, "views": 115305, "ts": 1790782382, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2105319629669466112/vid/avc1/1280x720/_h13xM8lluI5XUUx.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2105319629669466112/vid/avc1/1920x1080/ERpaqu5kGDojBj8e.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2105319629669466112/img/Jfz6YmT1Lzktn-Tg.jpg", "dur": 33}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.91, "thread": [], "tier": "must"}, {"id": "2112861576952676404", "url": "https://x.com/LuminaBench/status/2112861576952676404", "text": "🚨 Kimi K3.1 is now getting prepped in Kimi Code\n\nThere is a model switching warning that now includes Kimi K3.1 if you change model mid session\n\nNo exact time of launch but it won't be far away now", "name": "Lumina", "handle": "LuminaBench", "avatar": "https://pbs.twimg.com/profile_images/2062955151820787712/m39pUS7O_200x200.jpg", "likes": 305, "rts": 16, "replies": 15, "views": 22969, "ts": 1792580429, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVJivskW4AI8ejx.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.9, "thread": [], "tier": "must"}, {"id": "2112935427422527584", "url": "https://x.com/ArtificialAnlys/status/2112935427422527584", "text": "We've updated MLCR-AA, our leaderboard for Wisedocs' Medical Long Context Reasoning benchmark, with Claude Sonnet 5.5 and GPT-6 Astra now tied for the #1 score\n\nWe've updated how MLCR-AA prompts and grades models on @wisedocsai's benchmark, to better reflect how medical record review is done in practice. Models are now prompted as medical record reviewers, and asked to answer each part of a question in one paragraph with their conclusion and the supporting evidence from the record. Answers are graded by a new three-model judge panel, and we reviewed all 60 expert reference answers against their source records, refining 15.\n\nClaude Sonnet 5.5 (max with fallback) from @AnthropicAI and GPT-6 Astra (max) from @OpenAI are tied at the top with 41.7%, followed by GPT-6.1 Sol (max) at 38.3%. Qwen3.8 2.4T A95B from @Alibaba_Qwen is the leading open weights model at 30.6%.\n\nKey results from the updated MLCR-AA:\n\n➤ Medical record review remains far from solved: an answer passes only when it is both complete and accurate, and no model passes more than 42% of questions and the median model passes under 15%\n\n➤ Anthropic models lead on completeness, reaching the expert's conclusion with the right medical reasoning: Claude models hold the top 18 completeness scores across every model and effort level we tested, led by Claude Sonnet 5.5 (max with fallback) at 64.8%. The best non-Anthropic model is GPT-6 Astra (max) at 42.2%\n\n➤ OpenAI models lead on accuracy, citing the record without exaggeration or hallucination: OpenAI models hold the top 27 accuracy scores, led by GPT-6.1 Sol (max) at 96.7%, but answer fewer questions completely: GPT-6.1 Sol (max) is complete on 40.0% of questions\n\nWe would like to thank Wisedocs for building MLCR and for their collaboration in bringing it to Artificial Analysis", "name": "Artificial Analysis", "handle": "ArtificialAnlys", "avatar": "https://pbs.twimg.com/profile_images/2042402069320290304/A8C1lP07_200x200.jpg", "likes": 195, "rts": 16, "replies": 29, "views": 29934, "ts": 1792598036, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVKmYIbb0AAuF42.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.9, "thread": [], "tier": "must"}, {"id": "2112956460694954492", "url": "https://x.com/arikslep/status/2112956460694954492", "text": "We present OpenTac, an open, full-stack ecosystem for 3D tactile sensing on any robot surface.\n\nAnyone can design and fabricate high-density tactile skins for any part of their robot, then read them out, simulate them, and share data across different sensors.", "name": "Arik Slepyan", "handle": "arikslep", "avatar": "https://pbs.twimg.com/profile_images/2080412451573469185/Ff8R-YXj_200x200.jpg", "likes": 189, "rts": 27, "replies": 7, "views": 15336, "ts": 1792603051, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112950349816348673/vid/avc1/640x360/dKcVl61k4U1DUUD_.mp4?tag=14", "hd": "https://video.twimg.com/amplify_video/2112950349816348673/vid/avc1/1280x720/rC3YuQ3_BEYLRW8u.mp4?tag=14", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112950349816348673/img/49k0aoTnG6koBGaJ.jpg", "dur": 65}], "quote": null, "reply_to": null, "cat": "AI Video, Art & Music", "score": 5.9, "thread": [], "tier": "must"}, {"id": "2112900951661027483", "url": "https://x.com/karlarboledas/status/2112900951661027483", "text": "Los diseñadores de motion están en serio peligro, aquí está el porqué:\n\nUn agente de IA ahora puede modelar una escena 3D en Blender, animar un sitio web y renderizar un MP4 final. Tú lo describes, el agente lo construye.\n\nTres repos que hacen exactamente eso:\n\n-> HyperFrames: escribe HTML, obtén un video. Creado por HeyGen para agentes de IA. Pide una introducción de producto de 10 segundos con un título de entrada gradual y música de fondo, y el agente lo planea, lo anima y renderiza el MP4\nhttp://github.com/heygen-com/hyp\n\n-> MCP para Blender: conecta Blender a Claude o cualquier otro modelo. El agente crea objetos, construye escenas y las edita en 3D real mientras tú miras\nhttp://github.com/ahujasid/mcp-f\n\n-> Habilidades GSAP: las habilidades oficiales que enseñan a los agentes de codificación a animar la web correctamente con GSAP. Líneas de tiempo, efectos de desplazamiento, el material del que están hechas las páginas de aterrizaje premium\nhttp://github.com/greensock/gsap\n\nLa configuración para HyperFrames en Claude Code son dos líneas:\n\nclaude plugin marketplace add heygen-com/hyperframes\nclaude plugin install hyperframes@hyperframes\n\nLuego solo escribe /hyperframes:hyperframes y describe tu video.\n\nLa pila en una línea: Blender para el 3D, GSAP para el motion, HyperFrames para el renderizado final.\n\nguárdalo y sígueme para más → @karlarboledas", "name": "karla", "handle": "karlarboledas", "avatar": "https://pbs.twimg.com/profile_images/2106955765348974592/5Ul1ntrn_200x200.jpg", "likes": 180, "rts": 39, "replies": 16, "views": 10298, "ts": 1792589817, "media": [{"type": "video", "url": "https://video.twimg.com/amplify_video/2112900906190618624/vid/avc1/480x678/ROTOaNMOmSolDfMn.mp4?tag=29", "hd": "https://video.twimg.com/amplify_video/2112900906190618624/vid/avc1/720x1018/LDjZzZew2kGuvPVV.mp4?tag=29", "thumb": "https://pbs.twimg.com/amplify_video_thumb/2112900906190618624/img/gfZfzRaUTAa-sZDn.jpg", "dur": 19}], "quote": null, "reply_to": null, "cat": "AI Models & Labs", "score": 5.89, "thread": [], "tier": "must"}, {"id": "2113034721475072177", "url": "https://x.com/teortaxesTex/status/2113034721475072177", "text": "> not even Sol 6 level\nSeeing as Sol is a 300B model, grim…", "name": "Teortaxes▶️ (DeepSeek 推特🐋铁粉 2023 – ∞)", "handle": "teortaxesTex", "avatar": "https://pbs.twimg.com/profile_images/1652169745037242368/KRPTShbG_200x200.jpg", "likes": 190, "rts": 2, "replies": 11, "views": 33377, "ts": 1792621710, "media": [], "quote": {"id": "2112719571232977019", "url": "https://x.com/onloglogn/status/2112719571232977019", "text": "We just added @deepseek_ai's V4.1-Flash-1017 to RSI-Inference Bench http://rsi-inference.com , and it's now the #1 open model  🐳\n\nIt surpasses GLM-5.3 to take #8 on the leaderboard.\n\n- Day-0 support: 7th, hidden tests passed 35% → 62% (Pass@1 still at 0%)\n- Inference optimization: 7th, 1.23× speed-up", "name": "Ruixiang Zhang", "handle": "onloglogn", "avatar": "https://pbs.twimg.com/profile_images/1859067710615023616/ydbVmgo1_200x200.jpg", "likes": 207, "rts": 15, "replies": 7, "views": 48928, "ts": 1792546572, "media": [{"type": "gif", "url": "https://video.twimg.com/tweet_video/HVHi0PSa0AArGnk.mp4", "hd": "https://video.twimg.com/tweet_video/HVHi0PSa0AArGnk.mp4", "thumb": "https://pbs.twimg.com/tweet_video_thumb/HVHi0PSa0AArGnk.jpg", "dur": 0}], "quote": null, "reply_to": null}, "reply_to": null, "cat": "AI Models & Labs", "score": 5.89, "thread": [], "tier": "must"}, {"id": "2112998543065600047", "url": "https://x.com/SawyerMerritt/status/2112998543065600047", "text": "Tesla has just released its Q3 earnings results.\n\nHighlights:\n• EPS (non-GAAP): $0.48 (vs. $0.45 est)\n• Revenue: $28.05B (vs. $28.3B est)\n• Adjusted EBITDA: $3.90B\n• Active FSD Subscriptions: 1.74M, up 67% YoY from 1.04M\n• Net income (GAAP): $787M\n• Free cash flow: $1.53B\n• Capex: $4.73B\n• Cash & marketable securities: $45.45B, up 9% YoY", "name": "Sawyer Merritt", "handle": "SawyerMerritt", "avatar": "https://pbs.twimg.com/profile_images/1837744842715082752/xH9vYixL_200x200.jpg", "likes": 2732, "rts": 254, "replies": 130, "views": 1005449, "ts": 1792613084, "media": [{"type": "photo", "url": "https://pbs.twimg.com/media/HVLg0bgXsAAnRtf.jpg?name=orig"}], "quote": null, "reply_to": null, "cat": "Money & Startups", "score": 5.88, "thread": [], "tier": "must"}, {"id": "2112831175324565967", "url": "https://x.com/pistol147/status/2112831175324565967", "text": "A statement on yesterday…..\n\nEverything I said in that interview was true. However, rest assured I’m doing my best to turn things round. \n\nI have been in a mental health clinic for the last 10 weeks, finally discharging so I could attempt to play in Belfast\n\nI owed that to my family, in particular my daughter to see me play for what could be the last time….. I also owed it to the fans who have supported me throughout my 21 years on tour\n\nI also owed that to World Snooker who have been amazing from day on in all this, in particular Simon Brownell and Neil Tomkins who have remained in touch regularly, even Simon paying me a visit in the clinic itself\n\nI’m not ok, but I’m ok in that itself. I’ve been much worse in the last few months than you saw yesterday. I literally didn’t see a future in anything…..\n\nMy daughter kept me going, the therapists, staff and all the other patients were amazing and helped me through some really dark days\n\nI see the light now that I couldn’t see before but I do now. I also know it won’t happen overnight. I’m a work in progress!!! My fight and determination on the table has always been there for ones to see. I need to show those same fighting qualities off it now for a while\n\nPlease don’t detract anything from Jordan yesterday, he’s been aware of my struggles and that can’t have been easy to play in but he handled it with grace and skill as I knew he would. Im proud to call him a friend\n\nI hope the rest of the event is a success and I will continue my treatments going forward and then see what’s ahead\n\nThank you to every single message I have received on here, instagram, Facebook, text messages and WhatsApp’s, I’ve seen them all but a bit overwhelmed to reply right now. Just know that they have helped me a lot but I’m not going anywhere just yet!!!! I have so much to live for and this is only the beginning of my new journey \n\nAlso, I was not made to do any interviews, I was simply given a choice and felt I owed it to everyone to speak. The media team at WST have been incredible through all this too\n\nThank you all x", "name": "Mark Allen", "handle": "pistol147", "avatar": "https://pbs.twimg.com/profile_images/736320826413330432/1lXeDz82_200x200.jpg", "likes": 50504, "rts": 1925, "replies": 3185, "views": 1309270, "ts": 1792573181, "media": [], "quote": null, "reply_to": null, "cat": "Everything Else", "score": 5.87, "thread": [], "tier": "must"}]);